insert into public.aircraft_profiles (id, profile, status, display_order)
values ('b-21', '{"id":"b-21","name":"B-21 Raider","subtitle":"从试飞到生产，追踪一架新飞机的成长。","domain":"军用","maker":"Northrop Grumman","stage":"试飞 / 低速初始生产","checkedAt":"2026-10-09","aliases":["B-21","B21"],"summary":"B-21 是正在试飞的隐身轰炸机。这个档案沿着公开的工程节点追踪它：设计审查、测试机加入、机组配置与总装线扩建；参数只记录可核对的官方信息。","latest":{"title":"新总装线动工，扩大生产能力","date":"2026-10-08","eventDate":"2026-09-29","summary":"美国空军公告披露，Plant 42 的新总装线于 9 月 29 日动工。扩产协议提出年产能增加 25%；公告同时确认飞机仍在试飞，并预计 2027 年在 Ellsworth 基地接收飞机。","source":"usaf-production"},"specs":[{"label":"机型定位","value":"隐身轰炸机","evidence":"官方公布","note":"官方事实表描述的项目定位；具体性能仍需以公开测试结果为准。","source":"usaf-facts"},{"label":"机组配置","value":"2 名飞行员","evidence":"官方公布","note":"2026 年 7 月 9 日公布的配置，不从座舱照片推测人数。","source":"usaf-crew"},{"label":"第二架测试机","value":"2025.09.11 抵达 Edwards","evidence":"官方公布","note":"这是有来源的试飞节点，不代表截至今天的全部测试机数量。","source":"usaf-second"},{"label":"生产状态","value":"低速初始生产","evidence":"官方公布","note":"2025 年 9 月公告确认试飞、地面测试与低速初始生产同时推进。","source":"usaf-second"},{"label":"年产能提升","value":"+25%（扩产计划）","evidence":"研制目标","note":"这是扩产协议的产能目标，不是已完成交付的增长率；公告没有给出每年架数基线。","source":"usaf-production"},{"label":"首个接收基地 / 时间","value":"Ellsworth / 预计 2027 年","evidence":"研制目标","note":"采用 2026 年 10 月公告的最新计划；飞机抵达基地不等同于已形成作战能力。","source":"usaf-production"},{"label":"尺寸与重量","value":"所核对资料未公开","evidence":"未公开","note":"本档案引用的官方事实表未列出翼展、机长或重量，不使用图片比例推算值填充。","source":"usaf-facts"},{"label":"速度、航程与发动机参数","value":"所核对资料未公开","evidence":"未公开","note":"引用的官方事实表没有这些定量指标，不能将设计定位当成实测性能。","source":"usaf-facts"}],"design":[{"title":"开放系统架构：给未来升级留出接口","text":"官方事实表将降低集成风险、支持后续现代化列为开放系统架构的设计目的。可以研究模块与接口怎样影响升级成本，但公开资料不足以确认内部实现细节。","source":"usaf-facts"},{"title":"多机测试也在检验维护体系","text":"第二架测试机的加入让维护人员能够同时处理多架飞机，验证工具、技术资料与保障流程。试飞项目除了验证飞行表现，也需要验证一架飞机怎样被持续维护。","source":"usaf-second"},{"title":"机组数量也是系统设计的结果","text":"官方在分析飞机能力之后确定两名飞行员的配置。由此可以讨论任务时长、工作负荷与自动化的关系；公告没有披露具体人机界面，不能据此推断自动化水平。","source":"usaf-crew"},{"title":"工厂扩建与飞机验证是两条进度线","text":"新总装线的建设服务于产能扩张，而飞机仍在试飞。持续跟踪时，应分别记录设施进度、生产能力和实际交付，避免把一项计划当成另一项成果。","source":"usaf-production"}],"questions":["试飞、地面测试和低速初始生产为什么可能同时进行？","开放系统架构怎样帮助一架飞机在长期使用中升级？","在只有公开照片和概述的情况下，哪些设计判断有证据，哪些只能作为问题？","产能增长、交付增长与飞机抵达基地，分别需要什么证据才能确认？"],"timeline":[{"date":"2015-10-27","title":"工程与制造研制合同授予","text":"美国空军将 B-21 工程与制造研制合同授予 Northrop Grumman。","source":"usaf-facts"},{"date":"2018","title":"完成关键设计审查","text":"官方事实表记录了针对设计成熟度、稳定性与风险的项目级审查；没有列出具体日期。","source":"usaf-facts"},{"date":"2025-09-11","title":"第二架试飞飞机加入","text":"第二架测试机抵达 Edwards，扩展测试和维护训练能力。","source":"usaf-second"},{"date":"2026-07-09","title":"公布双飞行员配置","text":"美国空军发布正式机组配置，并介绍相关飞行员转训安排。","source":"usaf-crew"},{"date":"2026-09-29","title":"新总装线动工","text":"Plant 42 扩建动工；消息于 10 月 8 日发布。事件日和报道日分开记录。","source":"usaf-production"},{"date":"2027（计划）","title":"预计在 Ellsworth 接收飞机","text":"这是 2026 年 10 月公告的预期节点，需继续核对实际抵达进展。","source":"usaf-production"}],"sources":[{"id":"usaf-production","name":"美国空军","title":"DAF, Northrop Grumman break ground on B-21 production facility","url":"https://www.af.mil/News/Article-Display/Article/4621692/daf-northrop-grumman-break-ground-on-b-21-production-facility/","published":"2026-10-08"},{"id":"usaf-crew","name":"美国空军","title":"Air Force announces B-21 Raider crew complement","url":"https://www.afrc.af.mil/News/Article/4538932/air-force-announces-b-21-raider-crew-complement/","published":"2026-07-09"},{"id":"usaf-second","name":"美国空军","title":"US Air Force announces arrival of second B-21 test aircraft at Edwards AFB","url":"https://www.af.mil/News/Article-Display/Article/4301502/us-air-force-announces-arrival-of-second-b-21-test-aircraft-at-edwards-afb/","published":"2025-09-11"},{"id":"usaf-facts","name":"美国空军事实表","title":"B-21 Raider","url":"https://www.af.mil/About-Us/Fact-Sheets/Display/Article/2682973/b-21-raider/"}]}'::jsonb, 'published', 3)
on conflict (id) do nothing;
